// HTTP-only preview entry. Production's scheduled handler is not imported.
// @ts-ignore generated by opennextjs-cloudflare build
import handler from "./.open-next/worker.js"

export default {
  async fetch(request: Request, env: unknown, context: unknown): Promise<Response> {
    const response = await handler.fetch(request, env, context)
    const headers = new Headers(response.headers)
    headers.set("Permissions-Policy", [
      'camera=(self "https://cofferwallet.com")',
      'clipboard-read=(self "https://cofferwallet.com")',
      'clipboard-write=(self "https://cofferwallet.com")',
      'publickey-credentials-get=(self "https://cofferwallet.com")',
      'publickey-credentials-create=(self "https://cofferwallet.com")',
    ].join(", "))
    return new Response(response.body, { status: response.status, statusText: response.statusText, headers })
  },
}
